SELECT BNK_NO, ECC_IBF_GET_BANK_NAME(BNK_NO) AS BNK_NAME, PRODUCT_ID, (SELECT FUNDNM FROM FUNDINFO WHERE ROWNUM = 1 AND FUNDID = PRODUCT_ID) AS PRODUCT_NAME, APKIND, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) AS APKIND_NAME, STRAMT, ENDAMT, STRDATE, ENDDATE, TO_CHAR(TO_DATE(STRDATE,'YYYYMMDD'),'YYYY-MM-DD') AS STRDATEFORMAT, TO_CHAR(TO_DATE(ENDDATE,'YYYYMMDD'),'YYYY-MM-DD') AS ENDDATEFORMAT, TO_CHAR(DISCOUNT,'FM9999999999999990.00') AS DISCOUNT, TO_CHAR(C_TIME,'YYYY-MM-DD HH24:MI:SS') C_TIME, C_MAN, ECC_IBF_GET_EMPLOYEE_NAME(C_MAN) AS C_MAN_NAME, E_TIME, E_MAN, ECC_IBF_GET_EMPLOYEE_NAME(E_MAN) AS E_MAN_NAME, STATUS, IBF_GET_PARAMNAME('SYSTEM','ECCDATAST',STATUS) AS STATUS_NAME FROM BANK_DISCOUNT WHERE 1=1 AND STATUS <> 'D'
AND BNK_NO = #{sp.bankName}
AND PRODUCT_ID = #{sp.productId}
AND APKIND = #{sp.apkind}
ORDER BY C_TIME DESC

SELECT BNK_NO, ECC_IBF_GET_BANK_NAME(BNK_NO) AS BNK_NAME, PRODUCT_ID, (SELECT FUNDNM FROM FUNDINFO WHERE ROWNUM = 1 AND FUNDID = PRODUCT_ID) AS PRODUCT_NAME, APKIND, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) AS APKIND_NAME, STRAMT, ENDAMT, STRDATE, ENDDATE, TO_CHAR(TO_DATE(STRDATE,'YYYYMMDD'),'YYYY-MM-DD') AS STRDATEFORMAT, TO_CHAR(TO_DATE(ENDDATE,'YYYYMMDD'),'YYYY-MM-DD') AS ENDDATEFORMAT, TO_CHAR(DISCOUNT,'FM9999999999999990.00') AS DISCOUNT, TO_CHAR(C_TIME,'YYYY-MM-DD HH24:MI:SS') C_TIME, C_MAN, ECC_IBF_GET_EMPLOYEE_NAME(C_MAN) AS C_MAN_NAME, E_TIME, E_MAN, ECC_IBF_GET_EMPLOYEE_NAME(E_MAN) AS E_MAN_NAME, STATUS, IBF_GET_PARAMNAME('SYSTEM','ECCDATAST',STATUS) AS STATUS_NAME FROM BANK_DISCOUNT WHERE 1=1 AND STATUS <> 'D'
AND BNK_NO = #{sp.bankName}
AND PRODUCT_ID = #{sp.productId}
AND APKIND = #{sp.apkind}
ORDER BY C_TIME DESC

mapper.update:
UPDATE BANK_DISCOUNT
   SET STRAMT   = #{strAmt},
       ENDAMT   = #{endAmt},
       STRDATE  = #{strDate},
       ENDDATE  = #{endDate},
       DISCOUNT = #{discount},
       E_TIME   = SYSDATE,
       E_MAN    = #{modifyId},
       STATUS   = #{status}
 WHERE BNK_NO = #{bnkNo}
   AND PRODUCT_ID = #{productId}
   AND APKIND = #{apkind}
